private readonly Dictionary<Op, Func<Ctx, int, int>> handlers = new()
{
    [Op.Add] = (ctx, v) => ctx.Acc + v,
    [Op.Sub] = (ctx, v) => ctx.Acc - v,
};

int Dispatch(Op op, int arg) =>
    handlers.TryGetValue(op, out var handler)
        ? handler(ctx, arg)
        : throw new UnknownOpException(op);
